const state = {entries:[],notebooks:[],tags:[],settings:{},storage:{},selected:null,view:'journal',notebook:null,query:'',sort:'date',filters:{},bulk:false,checked:new Set(),calendar:new Date(),calendarDate:today(),prompt:Math.floor(Date.now()/86400000)%prompts.length,markdown:false,read:false,focus:false};
