async function api(path, method='GET', body) {
 const response = await fetch(path,{method,headers:{'Content-Type':'application/json','X-Diary-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)});
 const data = await response.json().catch(()=>({}));
 if(!response.ok) throw new Error(data.error || `Request failed (${response.status})`);
 return data;
}
function toast(message) { $('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500); }
function fail(error) { console.error(error);toast(error.message || 'Something went wrong. Your writing is still here.'); }
function textOf(html) { const el=document.createElement('div');el.innerHTML=html||'';const blocks=new Set(['P','DIV','H1','H2','H3','H4','H5','H6','LI','BLOCKQUOTE','PRE','TR','TABLE','UL','OL']);function walk(node){if(node.nodeType===3)return node.textContent;if(node.nodeType!==1)return '';if(node.tagName==='BR')return '\n';if(node.matches('span[data-latex]'))return node.getAttribute('data-latex');const text=[...node.childNodes].map(walk).join('');return text+(blocks.has(node.tagName)?'\n':node.tagName==='TD'||node.tagName==='TH'?'\t':'');}return [...el.childNodes].map(walk).join('').replace(/\n{3,}/g,'\n\n').trim(); }
function words(html) { return textOf(html).trim().split(/\s+/u).filter(Boolean).length; }
function entryTitle(e) { return e.title || textOf(e.html).trim().split(/[\n.!?]/)[0].slice(0,70) || 'Untitled entry'; }
function sanitize(html) {
 const doc = new DOMParser().parseFromString(html||'','text/html');
 const allowed = new Set(['P','DIV','BR','B','STRONG','I','EM','U','S','STRIKE','H1','H2','H3','H4','UL','OL','LI','BLOCKQUOTE','PRE','CODE','HR','A','IMG','TABLE','TBODY','THEAD','TR','TD','TH','INPUT','LABEL','SPAN','SUP','SUB']);
 const blocked = new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','FORM','TEXTAREA','BUTTON']);
 function clean(node) {
  if(node.nodeType===3)return document.createTextNode(node.textContent);
  const fragment=document.createDocumentFragment();if(node.nodeType!==1||blocked.has(node.tagName))return fragment;
  let el=allowed.has(node.tagName)?document.createElement(node.tagName.toLowerCase()):fragment;
  if(node.tagName==='SPAN'&&equationSource(node.getAttribute('data-latex'))!==null){el.setAttribute('data-latex',node.getAttribute('data-latex'));el.textContent=node.getAttribute('data-latex');return el;}
  if(node.tagName==='A') { const href=node.getAttribute('href')||''; if(/^https?:\/\//i.test(href)||/^mailto:/i.test(href)){el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');} }
  if(node.tagName==='IMG') { const src=node.getAttribute('src')||'';if(!/^\/media\/[a-zA-Z0-9_-]+$/.test(src))return fragment;el.setAttribute('src',src);el.setAttribute('alt',node.getAttribute('alt')||'Diary photo');el.setAttribute('loading','lazy'); }
  if(node.tagName==='INPUT') {if(node.getAttribute('type')!=='checkbox')return fragment;el.setAttribute('type','checkbox');el.setAttribute('aria-label','Checklist item');if(node.hasAttribute('checked'))el.setAttribute('checked','');}
  for(const child of [...node.childNodes])el.appendChild(clean(child));
  return el;
 }
 const out=document.createElement('div');for(const child of [...doc.body.childNodes])out.appendChild(clean(child));return out.innerHTML;
}
function highlight(str) {const q=state.query.trim();if(!q)return esc(str);const pieces=String(str).split(new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'gi'));return pieces.map(x=>x.toLowerCase()===q.toLowerCase()?`<mark>${esc(x)}</mark>`:esc(x)).join('');}
function activeEntries(){return state.entries.filter(e=>!e.deletedAt);}
function filteredEntries() {
 return state.entries.filter(e=>{
  if(state.view==='trash'? !e.deletedAt : e.deletedAt)return false;
  if(state.view==='favorites'&&!e.favorite)return false;
  if(state.view==='onthisday'&&(e.date.slice(5)!==today().slice(5)||e.date.slice(0,4)===today().slice(0,4)))return false;
  if(state.notebook&&e.notebookId!==state.notebook)return false;
  if(state.query&&!`${entryTitle(e)} ${textOf(e.html)} ${e.tags.join(' ')}`.toLowerCase().includes(state.query.toLowerCase()))return false;
  const f=state.filters;if(f.tag&&!e.tags.includes(f.tag))return false;if(f.mood&&String(e.mood)!==f.mood)return false;if(f.from&&e.date<f.from)return false;if(f.to&&e.date>f.to)return false;if(f.media&&!e.attachments?.length)return false;
  return true;
 }).sort((a,b)=>state.sort==='title'?entryTitle(a).localeCompare(entryTitle(b)):state.sort==='words'?b.wordCount-a.wordCount:state.sort==='updated'?b.updatedAt.localeCompare(a.updatedAt):state.sort==='oldest'?a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt):b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
}
function renderNav() {
 const live=activeEntries(); const nav=[['journal','book','All entries',live.length],['calendar','calendar','Calendar'],['favorites','star','Favorites',live.filter(e=>e.favorite).length],['onthisday','clock','On this day'],['insights','chart','Insights'],['trash','trash','Trash',state.entries.filter(e=>e.deletedAt).length]];
 $('#main-nav').innerHTML=nav.map(([v,i,t,c])=>`<button class="nav-button ${state.view===v&&!state.notebook?'active':''}" data-view="${v}">${icon(i)}<span>${t}</span>${c?`<span class="count">${c}</span>`:''}</button>`).join('');
 $('#main-nav').insertAdjacentHTML('beforeend',`<button class="nav-button mobile-settings ${state.view==='settings'?'active':''}" data-view="settings">${icon('settings')} Settings</button>`);
 $('#notebooks-nav').innerHTML=state.notebooks.map(n=>`<div class="notebook-row"><button class="nav-button ${state.notebook===n.id?'active':''}" data-notebook="${esc(n.id)}">${icon('folder')}<span>${esc(n.name)}</span><span class="count">${live.filter(e=>e.notebookId===n.id).length}</span></button><button class="icon-button notebook-more" data-manage-notebook="${esc(n.id)}" aria-label="Manage ${esc(n.name)}">${icon('more')}</button></div>`).join('')||'<p class="notebook-hint">Give your thoughts a home.</p>';
 $$('[data-view="settings"]').forEach(el=>el.classList.toggle('active',state.view==='settings'));
}
